select id, account_id, txn_time, is_flagged, ntile(5) over (partition by merchant order by amount asc, id asc) as amount_bucket, last_value(merchant, true) over (partition by merchant order by amount asc, id asc rows between unbounded preceding and current row) as last_known_merchant, avg(amount) over (partition by account_id order by txn_time asc, id asc rows between 3 preceding and 1 preceding) as amount_avg_3_prior, round(amount / sum(amount) over (partition by merchant, txn_type), 4) as amount_share from transactions;
